import React from 'react';
import { Briefcase, GraduationCap, MapPin } from 'lucide-react';
import { portfolioData } from '../../data/portfolioData';
import { useLanguage } from '../../context/LanguageContext';
import { PageWrapper } from '../../shared/components/PageWrapper';

const Experience = () => {
  const { language } = useLanguage();
  const copy = {
    fr: {
      eyebrow: 'Parcours',
      title: 'Formation et expérience.',
      intro: 'Les étapes qui m’ont permis de développer mes compétences.',
      work: 'Expérience & projets',
      education: 'Formation'
    },
    en: {
      eyebrow: 'Experience',
      title: 'Education and experience.',
      intro: 'The steps that have helped me develop my skills.',
      work: 'Experience & projects',
      education: 'Education'
    },
    ar: {
      eyebrow: 'المسار',
      title: 'التكوين والخبرة.',
      intro: 'المراحل التي ساعدتني على تطوير مهاراتي.',
      work: 'الخبرة والمشاريع',
      education: 'التكوين'
    },
    es: {
      eyebrow: 'Trayectoria',
      title: 'Formación y experiencia.',
      intro: 'Etapas que me han ayudado a desarrollar mis habilidades.',
      work: 'Experiencia y proyectos',
      education: 'Formación'
    }
  }[language];
  const experiences = [...portfolioData.experience].reverse();
  const education = portfolioData.education;

  const entries = [
    ...experiences.map((item) => ({ ...item, type: 'work' })),
    ...education.map((item) => ({ ...item, type: 'education' }))
  ];

  return (
    <PageWrapper>
      <header className="max-w-3xl">
        <p className="eyebrow">{copy.eyebrow}</p>
        <h1 className="display-heading mt-3 text-4xl leading-tight sm:text-5xl">{copy.title}</h1>
        <p className="mt-4 text-base leading-7 text-[var(--muted)]">{copy.intro}</p>
      </header>

      <div className="mt-12 grid gap-12 md:grid-cols-[1fr_2fr] md:gap-20">
        <div className="space-y-3">
          <div className="flex items-center gap-3">
            <Briefcase size={18} className="text-[var(--accent)]" />
            <h2 className="text-lg font-semibold">{copy.work}</h2>
          </div>
          <p className="text-sm leading-6 text-[var(--muted)]">{portfolioData.common[language].timelineDesc}</p>
          <div className="flex items-center gap-3 pt-5">
            <GraduationCap size={18} className="text-[var(--accent)]" />
            <h2 className="text-lg font-semibold">{copy.education}</h2>
          </div>
        </div>

        <ol className="relative space-y-0 border-s border-[var(--line)]">
          {entries.map((item) => {
            const details = item[language];
            const Icon = item.type === 'work' ? Briefcase : GraduationCap;
            const sectionLabel = item.type === 'work' ? copy.work : copy.education;

            return (
              <li key={`${details.title}-${details.period}`} className="relative pb-9 ps-7 last:pb-0">
                <span className="absolute -start-[9px] top-1 flex h-4 w-4 items-center justify-center rounded-full border-2 border-[var(--page)] bg-[var(--accent)]" />
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
                  <span className="text-xs font-semibold uppercase tracking-[0.1em] text-[var(--accent)]">{sectionLabel} · {details.period}</span>
                </div>
                <h3 className="mt-2 text-lg font-semibold">{details.title}</h3>
                <p className="mt-1 flex items-center gap-1.5 text-sm text-[var(--muted)]">
                  {item.type === 'work' ? <Icon size={14} /> : <MapPin size={14} />}
                  {details.place}
                </p>
                <p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--muted)]">{details.desc}</p>
              </li>
            );
          })}
        </ol>
      </div>
    </PageWrapper>
  );
};

export default Experience;
